// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success, "deposit failed");

        address nonOwner = address(0x123);
        address target = address(0x456);

        vm.prank(nonOwner);

        bool ok;
        try c.sendMoney(target, 0.5 ether) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok == false, "Reference contract should have reverted");
    }
}
